              end_datetime: {
                type: 'string',
                description: 'New end date and time in ISO format (optional)'
              },
              time_zone: {
                type: 'string',
                description: 'Legacy field. Patient date/time interpretation uses the AI Assistant timezone, which inherits the company timezone when unset.'
              },
